import Foundation

struct Dependency: Identifiable, Hashable, Sendable {
    enum Kind: Hashable, Sendable {
        /// Installed with `winetricks <verb>`
        case winetricks(verb: String)
        /// Downloaded directly and its installer is run inside Wine
        case installer(url: URL, archiveIsZip: Bool)
        /// Generated by Miro: a forwarder DLL for an API set Wine 7.7 doesn't ship
        case shim(fileName: String, exports: [ShimExport])
    }

    enum Category: String, Sendable, CaseIterable {
        case visualCpp = "Visual C++ 런타임"
        case directX = "DirectX"
        case audioInput = "오디오 · 입력"
        case fonts = "글꼴"
        case dotnet = ".NET · XNA"
        case media = "미디어 코덱"
        case rpgMaker = "RPG Maker RTP"
        case compat = "Windows 호환 파일"
    }

    let id: String
    let name: String
    let detail: String
    let category: Category
    let kind: Kind
    /// Approximate download size in MB (shown next to the install button)
    let sizeMB: Int
    /// DLL names (lower-case). A trailing `*` matches a prefix.
    let dlls: [String]

    func provides(_ dll: String) -> Bool {
        let dll = dll.lowercased()
        return dlls.contains { pattern in
            pattern.hasSuffix("*") ? dll.hasPrefix(pattern.dropLast()) : dll == pattern
        }
    }

    var isWinetricks: Bool {
        if case .winetricks = kind { return true }
        return false
    }

    var isShim: Bool {
        if case .shim = kind { return true }
        return false
    }
}

