    /// Packages Miro may install on its own after a failed launch: vendor redistributables (Microsoft, NVIDIA,
    /// OpenAL) that are widely used with Wine. With the winetricks script Miro pins (RuntimeManager), every file
    /// they download carries a SHA-256 and comes from the vendor's server, except the DirectX 9 runtimes
    /// Microsoft re-signed or took down, which come from copies with the original file's SHA-256.
    /// Left out on purpose, so only installed when the player asks: vcrun6 (overwrites Wine's oleaut32 and
    /// msvcrt), d3dcompiler_47 (Wine ships one; winetricks takes it from a third-party repository), .NET and
    /// codecs that replace Wine's own components, and installers that open a window.
    static let autoInstallIDs: Set<String> = [
        "vcrun2022", "vcrun2013", "vcrun2012", "vcrun2010", "vcrun2008", "vcrun2005",
        "d3dx9", "d3dx10", "d3dx11_43", "d3dcompiler_43",
        "xact", "xinput", "directmusic", "physx", "openal"
    ]

    /// Optional, slow or rarely needed — offered as a checkbox during setup
    static let extraIDs = ["dotnet48", "xna40", "dotnetdesktop8", "lavfilters"]

    /// Miro-generated files that are installed automatically (no download needed)
    static var shims: [Dependency] { all.filter(\.isShim) }

    static func dependency(_ id: String) -> Dependency? {
        all.first { $0.id == id }
    }

    static func dependencies(_ ids: [String]) -> [Dependency] {
        ids.compactMap(dependency)
    }

    /// The package that provides a DLL, if Miro knows one
    static func provider(of dll: String) -> Dependency? {
        all.first { $0.provides(dll) }
    }

    /// Libraries that games made with `engine` usually need
    static func recommended(for engine: GameEngine) -> [String] {
        switch engine {
        case .unity: return ["winrt-robuffer", "vcrun2022", "d3dcompiler_47"]
        case .unreal: return ["vcrun2022", "d3dcompiler_47", "xact", "physx"]
        case .rpgMaker2000: return ["directmusic", "fakekorean", "fakejapanese"]
        case .rpgMakerXP, .rpgMakerVX, .rpgMakerVXAce: return ["fakekorean", "fakejapanese"]
        case .rpgMakerMV, .rpgMakerMZ: return ["d3dcompiler_47", "fakekorean", "fakejapanese"]
        case .wolfRPG: return ["d3dx9", "fakejapanese", "fakekorean"]
        case .godot: return ["vcrun2022"]
        case .gameMaker: return ["vcrun2022", "d3dx9", "d3dcompiler_47"]
        case .kirikiri: return ["fakejapanese", "fakekorean", "lavfilters"]
        case .nwjs, .electron: return ["d3dcompiler_47"]
        case .dotnet: return ["dotnet48"]
        case .xna: return ["xna40", "dotnet48"]
        case .renpy, .unknown: return []
        }
    }
